H('397.d.14.F',4,"Fluid moves at 2 meters per second through a pipe with 0.01 square meters of area. The flow rate is:","0.02 cubic meters per second",["0.2 cubic meters per second","200 cubic meters per second","0.005 cubic meters per second"],"0.01 x 2 = 0.02.")
H('397.d.15.A',3,"The theoretical probability of rolling a 4 on a fair six-sided die is:","1/6",["1/4","4/6","1/2"],"One favorable outcome out of six.")
H('397.d.15.A',4,"The probability of getting two heads in a row on a fair coin is:","1/4",["1/2","2/3","1"],"1/2 x 1/2.")
H('397.d.15.B',3,"An experimenter flips a coin 50 times and gets 28 heads. The experimental frequency of heads is:","28/50",["1/2","22/50","50/28"],"Frequency = count / trials.")
H('397.d.15.B',4,"As the number of trials increases, experimental probability tends to move toward the:","theoretical probability",["opposite value","largest outcome","smallest outcome"],"The law of large numbers.")
H('397.d.15.C',3,"A Bernoulli process is a series of independent trials, each with:","two possible outcomes",["ten outcomes","no outcome","dependent outcomes"],"Success or failure.")
H('397.d.15.C',4,"Testing whether each manufactured part passes or fails inspection is best modeled as a:","Bernoulli process",["continuous curve","linear equation","vector"],"Each part is pass/fail.")
H('397.d.15.D',3,"The probability that a fair die does NOT show a 6 is:","5/6",["1/6","6/6","1/5"],"1 minus 1/6.")
H('397.d.15.D',4,"The probability of rolling a 1 OR a 2 on a fair die is:","1/3",["1/6","1/12","2/3"],"1/6 + 1/6.")
H('397.d.15.E',3,"Bayes's theorem is used to update the probability of an event after learning:","new information",["its color","the day of the week","the room"],"Bayes updates with evidence.")
H('397.d.15.E',4,"A diagnostic test result is used with a known failure rate to find the chance a part is defective. This uses:","conditional probability",["measurement of length","unit conversion","graphing a line"],"Bayes relates conditional probabilities.")
H('397.d.15.F',3,"The mean of the data set 2, 4, 6, 8 is:","5",["4","6","20"],"20 / 4 = 5.")
H('397.d.15.F',4,"The median of the data set 3, 5, 9 is:","5",["3","9","17"],"The middle value.")
H('397.d.15.G',3,"The range of the data set 4, 9, 15 is:","11",["28","9","15"],"15 minus 4.")
H('397.d.15.G',4,"The variance of a data set equals the square of its:","standard deviation",["mean","median","range"],"Variance = standard deviation squared.")
H('397.d.15.H',3,"A histogram displays the:","frequency of values in intervals",["names of people","map of a city","wiring paths"],"Histograms show distribution.")
H('397.d.15.H',4,"On a histogram of part lengths, a tall bar means:","many parts fall in that interval",["few parts","the part is long","the bar is wrong"],"Height shows frequency.")
H('397.d.16.A',3,"A cart travels 100 meters in 20 seconds. Its average speed is:","5 meters per second",["2,000 meters per second","0.2 meters per second","80 meters per second"],"100 / 20.")
H('397.d.16.A',4,"A cart speeds up from 0 to 10 meters per second in 5 seconds. Its acceleration is:","2 meters per second squared",["50 meters per second squared","0.5 meters per second squared","15 meters per second squared"],"10 / 5.")
H('397.d.16.B',3,"The acceleration due to gravity near Earth's surface is about:","9.8 meters per second squared",["1 meter per second squared","98 meters per second squared","0 meters per second squared"],"g is about 9.8.")
H('397.d.16.B',4,"A student times a dropped ball over a measured height. To find g experimentally, use the relation between distance and:","time squared",["color","mass only","wire length"],"d = 1/2 g t^2.")
H('397.d.16.C',3,"A projectile launches at 20 meters per second at 30 degrees. The initial vertical component is:","10 meters per second",["20 meters per second","34.6 meters per second","0 meters per second"],"20 x sin 30 = 10.")
H('397.d.16.C',4,"In projectile motion without air resistance, the horizontal velocity:","stays constant",["increases","decreases","reverses"],"No horizontal force acts.")
H('397.d.16.D',3,"Ignoring air resistance, the launch angle that gives the longest range on level ground is:","45 degrees",["90 degrees","0 degrees","10 degrees"],"Range peaks at 45.")
H('397.d.16.D',4,"Two launch angles that sum to 90 degrees, such as 30 and 60, give the same range because:","sin of twice the angle is the same",["gravity changes","mass changes","air thickens"],"sin 60 = sin 120.")

# ---------------- 398: Engineering Mathematics ----------------
H('398.d.1.A',3,"A hydraulic press operator needs 12 liters of fluid for each of 15 machines. How many liters are needed in all?","180",["27","150","1,800"],"12 x 15 = 180.")
H('398.d.1.A',4,"A pump moves 8 gallons each minute. How many gallons does it move in 2.5 hours?","1,200",["20","480","3,000"],"150 minutes x 8 = 1,200.")
H('398.d.1.B',3,"In a problem-solving model, deciding which formula to use happens while:","formulating a plan",["presenting the result","checking units afterward","closing the project"],"Planning picks the method.")
H('398.d.1.B',4,"A cylinder's computed stroke time is 0.002 seconds, which seems far too small. Which step catches this?","evaluating the solution for reasonableness",["analyzing the given data","choosing a pen","printing the result"],"Reasonableness checks expose errors.")
H('398.d.1.C',3,"To square 12 and cube 7 quickly with accuracy, a technician could use a:","scientific calculator",["ruler","compass","scale of weights"],"Calculators handle powers.")
H('398.d.1.C',4,"Sketching a lever on paper with arrows for forces is a tool that helps to:","visualize a problem before calculating",["avoid all math","replace measurement","delete the data"],"Sketches clarify setups.")
H('398.d.1.D',3,"A technician explaining a pressure calculation to a customer should communicate using:","clear steps and correct units",["slang only","no numbers","silence"],"Precise language aids understanding.")
H('398.d.1.D',4,"Writing '50 psi' instead of just '50' communicates the:","unit of the measurement",["color","owner","date only"],"Units give numbers meaning.")
H('398.d.1.E',3,"A table of pressures at different depths is a representation that helps to:","record and compare values",["hide values","remove units","add noise"],"Tables organize data.")
H('398.d.1.E',4,"A graph of flow rate against pump speed makes it easy to see a:","trend or relationship",["person's name","building color","phone number"],"Graphs show relationships.")
H('398.d.1.F',3,"If the pressure on a piston is raised to two times its value while the area stays the same, the force becomes:","twice as large",["half as large","unchanged","zero"],"F = P x A.")
H('398.d.1.F',4,"If a pipe's diameter is doubled, its cross-sectional area becomes:","four times larger",["twice as large","half as large","unchanged"],"Area depends on the diameter squared.")
H('398.d.1.G',3,"To justify a calculated beam load, an engineer should show the formula and the:","substituted values",["opinion","slogan","guess"],"Showing work justifies results.")
H('398.d.1.G',4,"A convincing mathematical argument includes definitions, steps, and:","a conclusion tied to the data",["a joke","a rumor","an unrelated claim"],"Arguments end with justified conclusions.")
H('398.d.2.A',3,"One U.S. gallon is about 3.8 liters, so 10 gallons per minute is about:","38 liters per minute",["2.6 liters per minute","13.8 liters per minute","380 liters per minute"],"10 x 3.8.")
H('398.d.2.A',4,"A flow of 76 liters per minute is about how many gallons per minute?","20",["288","0.05","76"],"76 / 3.8 = 20.")
H('398.d.2.B',3,"A flow meter test collects 5 gallons in 30 seconds. The flow rate is:","10 gallons per minute",["2.5 gallons per minute","150 gallons per minute","0.17 gallons per minute"],"5 gal x 2 = 10 per minute.")
H('398.d.2.B',4,"Averaging three flow meter readings of 9.8, 10.0, and 10.2 gallons per minute gives:","10.0 gallons per minute",["30 gallons per minute","9.8 gallons per minute","10.2 gallons per minute"],"Sum 30 / 3.")
H('398.d.2.C',3,"A cylinder piston has an area of 2 square inches and the system pressure is 1,000 psi. The force output is:","2,000 pounds",["500 pounds","1,002 pounds","998 pounds"],"F = P x A.")
H('398.d.2.C',4,"At constant flow, a smaller piston area makes the cylinder move:","faster, with less force",["slower, with more force","faster, with more force","at the same speed"],"Speed = flow / area; force = P x A.")
H('398.d.2.D',3,"A stroke displaces 1 gallon. At a flow rate of 5 gallons per minute, the stroke takes:","12 seconds",["5 seconds","60 seconds","0.2 seconds"],"1/5 minute = 12 seconds.")
H('398.d.2.D',4,"To halve the stroke time of a cylinder, you must:","double the flow rate",["halve the flow rate","double the stroke length","halve the pressure only"],"Time = volume / flow.")
H('398.d.3.A',3,"Two forces of 3 newtons and 4 newtons act at a right angle. The resultant force is:","5 newtons",["7 newtons","1 newton","12 newtons"],"Pythagorean theorem.")
H('398.d.3.A',4,"Two forces of 10 newtons and 6 newtons act in the same direction. The resultant is:","16 newtons",["4 newtons","60 newtons","8 newtons"],"Add collinear forces.")
H('398.d.3.B',3,"A hanging sign is at rest. The upward tension must equal the:","sign's weight",["wind speed","sign's color","wall height"],"Equilibrium balances forces.")
H('398.d.3.B',4,"A 200-newton box sits at rest on a floor. The floor pushes up with:","200 newtons",["0 newtons","400 newtons","20 newtons"],"Net force is zero.")
H('398.d.3.C',3,"A free-body diagram of a box on a ramp includes weight, the normal force, and:","friction",["voltage","tax","heat index"],"Friction acts along the ramp.")
H('398.d.3.C',4,"On a free-body diagram, the arrow length usually represents the force's:","magnitude",["color","price","age"],"Longer arrows are larger forces.")
H('398.d.3.D',3,"A strain gauge's electrical resistance changes when it is:","stretched or compressed",["painted","named","cooled to zero"],"Strain changes the wire geometry.")
H('398.d.3.D',4,"A strain gauge on a beam can be used to calculate the force on the beam because strain relates to:","stress through the modulus of elasticity",["wire color","gauge brand","the battery label"],"Stress = E x strain.")
H('398.d.3.E',3,"A wrench applies a torque of 20 newton-meters to a bolt with a 0.5-meter lever arm. The force is:","40 newtons",["10 newtons","20.5 newtons","19.5 newtons"],"F = T / r.")
H('398.d.3.E',4,"A 50-newton force acts at a radius of 0.2 meters. The torque is:","10 newton-meters",["250 newton-meters","50.2 newton-meters","0.004 newton-meters"],"T = F x r.")
H('398.d.3.F',3,"For a seesaw in balance, the clockwise moments equal the:","counterclockwise moments",["weights only","lengths only","speeds"],"Moment equilibrium.")
H('398.d.3.F',4,"A 30-newton child sits 2 meters from the pivot. To balance, a 20-newton child must sit:","3 meters from the pivot on the other side",["1 meter from the pivot","2 meters from the pivot","6 meters from the pivot"],"30 x 2 = 20 x d, d = 3.")
H('398.d.3.G',3,"A beam of length 4 meters carries a 100-newton load at its center, supported at both ends. The maximum bending moment is:","100 newton-meters",["400 newton-meters","25 newton-meters","200 newton-meters"],"M = PL/4 = 100 x 4 / 4.")
H('398.d.3.G',4,"The bending moment in a simply supported beam is greatest:","under the load for a center-loaded beam",["at the supports","nowhere","outside the beam"],"Max moment is at the center.")
H('398.d.3.H',3,"Bending stress in a beam is calculated as the moment times the distance from the neutral axis, divided by the:","moment of inertia",["weight of the beam","color","length of the label"],"Stress = M c / I.")
H('398.d.3.H',4,"In a bending beam, the highest stress occurs at the:","outer surface farthest from the neutral axis",["neutral axis","exact center of the cross section","support bolts"],"Stress grows with distance from the neutral axis.")
H('398.d.3.I',3,"One step of a six-step method for truss forces is to draw a free-body diagram of the:","entire truss or a joint",["manager","lunchroom","receipt"],"Start with a free-body diagram.")
H('398.d.3.I',4,"At a truss joint, a technician writes equations for the sum of forces in the horizontal and vertical directions. This is the method of:","joints",["colors","rounding","sections of music"],"The method of joints.")
H('398.d.3.J',3,"A material with a higher modulus of elasticity is:","stiffer",["more flexible","lighter","cheaper"],"E measures stiffness.")
H('398.d.3.J',4,"Steel has a much higher modulus than rubber, so for the same load a steel beam deflects:","less",["more","exactly the same","backward"],"Higher E means less deflection.")
H('398.d.3.K',3,"Increasing the length of a beam while holding the load constant makes the deflection:","greater",["smaller","zero","unchanged"],"Deflection rises quickly with length.")
H('398.d.3.K',4,"Using a beam with a larger moment of inertia reduces:","deflection under load",["strength","stiffness","safety"],"More I means a stiffer beam.")
H('398.d.3.L',3,"Euler's formula predicts the critical load that makes a long thin column:","buckle",["melt","rust","float"],"Euler buckling.")
H('398.d.3.L',4,"A longer column of the same material and cross section has a critical buckling load that is:","lower",["higher","the same","infinite"],"Critical load falls with length squared.")
H('398.d.3.M',3,"A factor of safety compares the failure load to the:","expected working load",["cost","color","size of the label"],"FS = failure load / working load.")
H('398.d.3.M',4,"A column fails at 9,000 newtons and must carry 3,000 newtons. The factor of safety is:","3",["27,000","6,000","12,000"],"9,000 / 3,000.")
H('398.d.4.A',3,"In a right triangle, the sine of an angle equals the opposite side divided by the:","hypotenuse",["adjacent side","angle","perimeter"],"SOH.")
H('398.d.4.A',4,"A right triangle has an angle whose opposite side is 3 and adjacent side is 4. The tangent of the angle is:","0.75",["1.33","0.6","5"],"3 / 4.")
H('398.d.4.B',3,"A surveyor stands 20 meters from a tower and sights its top at 60 degrees above level. The tower's height is about:","34.6 meters",["11.5 meters","20 meters","40 meters"],"20 x tan 60 = 34.6.")
H('398.d.4.B',4,"A technician stands 20 meters from a pole and measures a 30 degree angle to its top. The pole is about:","11.5 meters",["34.6 meters","20 meters","10 meters"],"20 x tan 30 = 11.5.")
H('398.d.5.A',3,"A drawing is scaled 1 to 4 (drawing to real). A feature measures 3 inches on the drawing. The real feature is:","12 inches",["0.75 inches","7 inches","1 inch"],"3 x 4 = 12.")
H('398.d.5.A',4,"A bracket is 20 centimeters long and is drawn at half size. On the drawing it measures:","10 centimeters",["40 centimeters","20 centimeters","5 centimeters"],"Half of 20.")
H('398.d.5.B',3,"If a machine finishes 30 parts in one hour, its production rate is:","30 parts per hour",["2 hours per part","30 hours","60 parts"],"Rate is output per time.")
H('398.d.5.B',4,"Production time is the time to make one unit, while production rate is the number of units made per:","unit of time",["pound","volt","color"],"Rate = units / time.")
H('398.d.5.C',3,"A machine finishes one part every 40 seconds. In 1 hour it makes:","90 parts",["40 parts","144 parts","60 parts"],"3,600 / 40 = 90.")
H('398.d.5.C',4,"If cycle time is reduced from 50 seconds to 40 seconds, hourly output rises from 72 parts to:","90 parts",["80 parts","100 parts","60 parts"],"3,600 / 40 = 90.")
H('398.d.5.D',3,"A 4 to 1 reduction gear set has an input speed of 1,200 revolutions per minute. The output speed is:","300 revolutions per minute",["4,800 revolutions per minute","1,196 revolutions per minute","1,204 revolutions per minute"],"1,200 / 4.")
H('398.d.5.D',4,"An ideal gear reduction of 4 to 1 turns 10 newton-meters of input torque into:","40 newton-meters",["2.5 newton-meters","14 newton-meters","6 newton-meters"],"Torque multiplies by the ratio.")
H('398.d.5.E',3,"In a simple gear train, an odd number of gears (such as 3) makes the output turn:","in the same direction as the input",["in the opposite direction","not at all","at random"],"Each mesh reverses direction.")
H('398.d.5.E',4,"A two-gear train has an output that turns:","opposite to the input",["with the input","never","twice as fast always"],"One mesh reverses the direction.")
H('398.d.5.F',3,"To make an output slower but stronger than the input, the driving gear should be:","smaller than the driven gear",["larger than the driven gear","the same size always","removed"],"A smaller driver turning a larger gear reduces speed.")
H('398.d.5.F',4,"A motor turns at 1,800 revolutions per minute and the load needs 600. The gear ratio must be:","3 to 1",["1 to 3","2 to 1","6 to 1"],"1,800 / 600 = 3.")
