H('398.d.5.G',4,"If two meshing gears are placed too far apart, they will:","fail to mesh properly",["mesh better","run quieter","last longer"],"Center distance must fit the gear teeth.")
H('398.d.5.H',3,"A hole positioned at 2.000 inches with a tolerance of plus or minus 0.005 inch may measure as much as:","2.005 inches",["2.050 inches","2.500 inches","1.995 only"],"Upper limit is 2.000 + 0.005.")
H('398.d.5.H',4,"Stacking tolerances of several parts in an assembly can cause the total error to:","add up",["vanish","reverse","cancel always"],"Tolerances accumulate.")
H('398.d.5.I',3,"A part costs $2 in material and $3 in labor. The cost of 100 parts is:","$500",["$5","$200","$300"],"$5 x 100.")
H('398.d.5.I',4,"A machine costs $60 per hour to run and makes 120 parts per hour. The machine cost per part is:","$0.50",["$2.00","$7,200","$60.00"],"60 / 120.")
H('398.d.5.J',3,"For a milling cutter, a higher cutting speed with the same diameter requires a higher:","spindle speed",["part number","feed table","tool color"],"RPM scales with surface speed.")
H('398.d.5.J',4,"Using RPM = 4 x cutting speed / diameter, a 2-inch cutter at 100 feet per minute should spin at:","200 revolutions per minute",["50 revolutions per minute","800 revolutions per minute","20 revolutions per minute"],"4 x 100 / 2.")
H('398.d.5.K',3,"A two-flute cutter turns at 400 RPM with a chip load of 0.005 inch per tooth. The feed rate is:","4 inches per minute",["2 inches per minute","0.4 inches per minute","40 inches per minute"],"400 x 2 x 0.005 = 4.")
H('398.d.5.K',4,"Increasing the feed rate while keeping the speed the same increases the:","chip load",["spindle speed","tool color","part number"],"More feed per revolution means more chip load.")
H('398.d.5.L',3,"In an injection mold, a longer runner generally causes a:","larger pressure drop",["smaller pressure drop","zero pressure drop","pressure gain"],"Longer flow path means more resistance.")
H('398.d.5.L',4,"Thicker, hotter plastic flowing through a narrow passage makes the pressure needed to fill the mold:","higher",["lower","zero","unchanged always"],"Narrow flow paths and viscosity raise pressure.")
H('398.d.5.M',3,"A gate that is too small in an injection mold can cause:","incomplete filling or high shear",["perfect parts","lower pressure","faster cooling always"],"Small gates restrict flow.")
H('398.d.5.M',4,"A gate that is too large can leave:","a large mark that is hard to trim",["no mark","a weaker part always","an empty mold"],"Large gates leave visible vestiges.")
H('398.d.5.N',3,"The overall mold block size must be large enough to hold the cavity, the runners, and the:","cooling channels and walls",["workers","trucks","paperwork"],"Mold size includes support features.")
H('398.d.5.N',4,"A mold with more cavities generally needs a mold block that is:","larger",["smaller","the same","invisible"],"More cavities need more space.")
H('398.d.5.O',3,"In a multi-cavity mold, balanced runners are designed so each cavity:","fills at the same time",["fills last","stays empty","fills from the cavity next door"],"Balance gives uniform parts.")
H('398.d.5.O',4,"If runners to some cavities are longer than others, the parts from those cavities are likely to be:","underfilled or different in quality",["identical","stronger","cheaper"],"Unbalanced runners cause variation.")
H('398.d.6.A',3,"Using Ohm's law, a circuit with 24 volts across 8 ohms has a current of:","3 amperes",["192 amperes","32 amperes","0.33 amperes"],"I = V / R.")
H('398.d.6.A',4,"The power in a circuit with 5 amperes through 10 ohms is:","250 watts",["50 watts","2 watts","15 watts"],"P = I squared x R = 25 x 10.")
H('398.d.6.B',3,"A resistor of 4,700 ohms is written in engineering notation as:","4.7 kilohms",["47 kilohms","0.47 kilohms","4.7 megohms"],"4,700 = 4.7 x 10^3.")
H('398.d.6.B',4,"A current of 0.0033 amperes is written in engineering notation as:","3.3 milliamperes",["33 milliamperes","3.3 microamperes","0.33 milliamperes"],"10^-3 is milli.")
H('398.d.6.C',3,"Direct current flows in one direction, while alternating current:","reverses direction periodically",["never flows","flows in one direction only","stops at zero forever"],"AC alternates.")
H('398.d.6.C',4,"A 60 hertz alternating current completes how many cycles each second?","60",["6","600","1"],"Hertz means cycles per second.")
H('398.d.6.D',3,"An inductor in an AC circuit opposes changes in:","current",["color","resistor values only","mass"],"Inductors resist current change.")
H('398.d.6.D',4,"As the frequency of an AC signal rises, the opposition of an inductor:","increases",["decreases","stays zero","reverses"],"Inductive reactance rises with frequency.")
H('398.d.6.E',3,"A capacitor in an AC circuit passes alternating current but blocks:","steady direct current",["alternating current","all signals","nothing"],"Capacitors block DC after charging.")
H('398.d.6.E',4,"As the frequency of an AC signal rises, the opposition of a capacitor:","decreases",["increases","reverses","stays infinite"],"Capacitive reactance falls with frequency.")
H('398.d.6.F',3,"The time constant of an RC circuit is found by multiplying resistance by:","capacitance",["voltage","power","current"],"Tau = R x C.")
H('398.d.6.F',4,"A 10-kilohm resistor with a 100-microfarad capacitor gives a time constant of:","1 second",["10 seconds","0.1 seconds","1,000 seconds"],"10,000 x 0.0001 = 1.")
H('398.d.6.G',3,"A transformer with a 10 to 1 turns ratio steps 120 volts down to:","12 volts",["1,200 volts","110 volts","130 volts"],"120 / 10.")
H('398.d.6.G',4,"An ideal transformer steps voltage down by a factor of 10. The current on the secondary side is:","10 times larger",["10 times smaller","unchanged","zero"],"Power in equals power out.")
H('398.d.6.H',3,"The RMS value of an AC voltage with a 170-volt peak is about:","120 volts",["240 volts","170 volts","85 volts"],"170 / 1.414 = 120.")
H('398.d.6.H',4,"RMS voltage is useful because it equals the DC voltage that would deliver the same:","heating power",["color","frequency","weight"],"RMS matches DC power.")
H('398.d.6.I',3,"A 1-kilowatt motor runs for 8 hours. The energy used is:","8 kilowatt-hours",["1 kilowatt-hour","9 kilowatt-hours","0.125 kilowatt-hours"],"1 x 8.")
H('398.d.6.I',4,"Electricity costs $0.12 per kilowatt-hour. A 2-kilowatt motor running 5 hours costs:","$1.20",["$0.24","$10.00","$0.60"],"2 x 5 x 0.12.")
H('398.d.7.A',3,"A cylinder extends with 1,000 psi acting on a 4-square-inch piston face. The extension force is:","4,000 pounds",["250 pounds","1,004 pounds","996 pounds"],"F = P x A.")
H('398.d.7.A',4,"On the retraction stroke, a cylinder produces less force than on extension because the fluid acts on an area reduced by the:","piston rod",["cylinder paint","pump label","gauge"],"Rod area is subtracted on the rod side.")
H('398.d.7.B',3,"Absolute pressure is gage pressure plus:","atmospheric pressure",["zero","temperature","flow rate"],"Absolute = gage + atmospheric.")
H('398.d.7.B',4,"A perfect vacuum has an absolute pressure of:","zero",["14.7 psi","100 psi","1 atmosphere"],"Absolute zero pressure is a perfect vacuum.")
H('398.d.7.C',3,"The ideal gas law relates pressure, volume, temperature, and the:","amount of gas",["color of gas","brand of tank","height of room"],"PV = nRT.")
H('398.d.7.C',4,"Heating a sealed rigid tank of gas makes its pressure:","increase",["decrease","vanish","stay exactly the same"],"At fixed volume, pressure rises with temperature.")
H('398.d.7.D',3,"Air compressed to a gage pressure of 14.7 psi has an absolute pressure twice atmospheric, so 1 cubic foot of it equals how much free air?","2 cubic feet",["1 cubic foot","0.5 cubic feet","14.7 cubic feet"],"Absolute pressure ratio is 2.")
H('398.d.7.D',4,"A compressor delivers 10 cubic feet of free air per minute. If that air is compressed to three times atmospheric absolute pressure, the compressed volume is about:","3.3 cubic feet",["30 cubic feet","10 cubic feet","13 cubic feet"],"10 / 3.")
H('398.d.7.E',3,"Relative humidity describes how much water vapor the air holds compared with the most it can hold at that:","temperature",["color","weight","height of the sensor"],"Capacity depends on temperature.")
H('398.d.7.E',4,"When air cools to its dew point, water vapor begins to:","condense",["boil","vanish","freeze always"],"Condensation begins at the dew point.")
H('398.d.7.F',3,"Pump flow rate is commonly stated in gallons per minute or in:","liters per minute",["pounds per inch","volts per second","degrees per hour"],"Both are volume per time.")
H('398.d.7.F',4,"A pump rated at 50 gallons per minute delivers about how many liters per minute?","190",["13","380","50"],"50 x 3.8 = 190.")
H('398.d.7.G',3,"Water has a density of 1 kilogram per liter. A flow of 10 liters per minute is a mass flow of:","10 kilograms per minute",["1 kilogram per minute","0.1 kilograms per minute","100 kilograms per minute"],"Mass flow = density x volumetric flow.")
H('398.d.7.G',4,"A liquid twice as dense as water flows at 5 liters per minute. Its mass flow rate is:","10 kilograms per minute",["2.5 kilograms per minute","5 kilograms per minute","7 kilograms per minute"],"2 x 5 = 10.")
H('398.d.7.H',3,"One psi is about 6.9 kilopascals, so 100 psi is about:","690 kilopascals",["14.5 kilopascals","106.9 kilopascals","0.069 kilopascals"],"100 x 6.9 = 690.")
H('398.d.7.H',4,"Unit analysis means setting up conversions so unwanted units:","cancel out",["multiply","appear twice","are ignored"],"Cancel units to get the target unit.")
H('398.d.7.I',3,"For water, each psi is about 2.31 feet of head. A pressure of 5 psi equals a head of about:","11.6 feet",["2.2 feet","1.16 feet","116 feet"],"5 x 2.31 = 11.55.")
H('398.d.7.I',4,"Water rises in a vertical pipe to a height of 46.2 feet. The pressure at the bottom is:","20 psi",["46.2 psi","2.31 psi","107 psi"],"46.2 / 2.31 = 20.")
H('398.d.7.J',3,"Total dynamic head is the sum of the discharge head and the:","suction lift, as a positive head",["pump color","pipe label","driver name"],"TDH combines suction and discharge.")
H('398.d.7.J',4,"If friction in the piping gets worse, the pump's total dynamic head requirement:","rises",["falls","stays zero","reverses"],"More loss means more head needed.")
H('398.d.7.K',3,"Total head of a centrifugal pump can be measured with a pressure gauge on the suction side and another on the:","discharge side",["floor","motor","label"],"Compare suction and discharge pressure.")
H('398.d.7.K',4,"The head developed by a pump is the difference between the discharge pressure head and the:","suction pressure head",["room temperature","pipe color","shaft length"],"Head = discharge minus suction.")
H('398.d.7.L',3,"Flow in a pipe with a Reynolds number of 1,000 is:","laminar",["turbulent","solid","frozen"],"Below about 2,000 is laminar.")
H('398.d.7.L',4,"Flow with a Reynolds number of 10,000 is:","turbulent",["laminar","stationary","electric"],"Above about 4,000 is turbulent.")
H('398.d.7.M',3,"Friction head loss in a pipe increases when the pipe is:","longer",["shorter","wider","absent"],"Loss is proportional to length.")
H('398.d.7.M',4,"At the same flow, using a larger-diameter pipe makes friction head loss:","smaller",["larger","negative","identical"],"Larger pipes have less loss.")
H('398.d.7.N',3,"Total suction lift occurs when the liquid source is:","below the pump",["above the pump","at the pump height always","in the motor"],"Lift means the source is lower.")
H('398.d.7.N',4,"Total suction head applies when the liquid supply level is:","above the pump inlet",["below the pump","absent","empty"],"Head means the source is higher.")
H('398.d.7.O',3,"Hydraulic horsepower can be found from flow rate in gallons per minute times pressure in psi divided by:","1,714",["12","60","3.14"],"Hp = gpm x psi / 1,714.")
H('398.d.7.O',4,"A pump delivers 10 gallons per minute at 1,714 psi. The hydraulic horsepower is:","10",["1,714","171.4","0.0058"],"10 x 1,714 / 1,714.")
H('398.d.7.P',3,"A pump with an output of 8 horsepower and an efficiency of 80 percent requires a brake horsepower of:","10",["6.4","8","64"],"8 / 0.8 = 10.")
H('398.d.7.P',4,"Brake horsepower is always greater than hydraulic horsepower because of:","pump losses",["extra water","gravity pulling up","pipe color"],"Efficiency is below 100 percent.")
H('398.d.7.Q',3,"According to the pump affinity laws, doubling the impeller speed doubles the:","flow rate",["pipe length","fluid color","filter size"],"Flow is proportional to speed.")
H('398.d.7.Q',4,"Doubling the impeller speed increases the head developed by a factor of:","4",["2","1","8"],"Head varies with speed squared.")
H('398.d.7.R',3,"Increasing the impeller diameter generally moves the head capacity curve:","upward",["downward","to the left only","off the chart"],"A larger impeller produces more head.")
H('398.d.7.R',4,"Trimming an impeller to a smaller diameter lowers the pump's:","head and flow at a given speed",["motor color","pipe length","gauge size"],"Smaller impellers do less work on the fluid.")
H('398.d.7.S',3,"Net positive suction head available must be greater than the head required, or the pump may:","cavitate",["freeze","grow","float"],"Low NPSH causes cavitation.")
H('398.d.7.S',4,"Cavitation damages a pump through the formation and collapse of:","vapor bubbles",["sand grains","paint chips","magnets"],"Collapsing bubbles erode surfaces.")
H('398.d.8.A',3,"A steel rod has a stress of 20,000 psi and a modulus of 10,000,000 psi. Its strain is:","0.002",["500","0.2","2,000"],"Strain = stress / E.")
H('398.d.8.A',4,"A 100-inch rod has a strain of 0.002. Its elongation is:","0.2 inches",["0.002 inches","50,000 inches","20 inches"],"100 x 0.002.")
H('398.d.8.B',3,"A highly sensitive sensor produces:","a large output change for a small input change",["no output","the same value always","only noise"],"Sensitivity is output per unit input.")
H('398.d.8.B',4,"A foil gauge's gauge factor describes its sensitivity as the fractional change in resistance per unit:","strain",["time","color","mass"],"Gauge factor = (change in R / R) / strain.")
H('398.d.8.C',3,"A data-acquisition system reads sensor signals and records them on a:","computer",["wall","paintbrush","bicycle"],"DAQ systems log data digitally.")
H('398.d.8.C',4,"Sampling a sensor too slowly in a data-acquisition program can cause the loss of:","fast changes in the signal",["power","gravity","color"],"Low sample rates miss rapid events.")
H('398.d.8.D',3,"A 1,000-newton compression load acts on a post with a cross-sectional area of 0.002 square meters. The compressive stress is:","500,000 pascals",["2 pascals","1,002 pascals","200 pascals"],"1,000 / 0.002.")
H('398.d.8.D',4,"Doubling the area of a compression member, with the same load, makes the stress:","half as large",["twice as large","the same","four times larger"],"Stress = force / area.")
H('398.d.8.E',3,"A 600-newton shear force acts on a pin with an area of 0.003 square meters. The shear stress is:","200,000 pascals",["2 pascals","603 pascals","1,800 pascals"],"600 / 0.003.")
H('398.d.8.E',4,"A pin in double shear spreads the load over how many cross sections?","two",["one","zero","four"],"Double shear involves two planes.")
H('398.d.8.F',3,"For steel, the ultimate tensile strength in psi is roughly 500 times the Brinell hardness number. A Brinell hardness of 200 suggests about:","100,000 psi",["200 psi","500 psi","100 psi"],"200 x 500.")
H('398.d.8.F',4,"A harder steel generally has a higher:","tensile strength",["weight alone","color","price per label"],"Hardness correlates with strength.")
H('398.d.8.G',3,"Applying a factor of safety in a design means the part is designed to carry:","more than the expected load",["less than the expected load","no load","only its own weight"],"Safety factors add margin.")
H('398.d.8.G',4,"A material has an ultimate strength of 60,000 psi and a design stress of 15,000 psi. The factor of safety is:","4",["45,000","0.25","75,000"],"60,000 / 15,000.")
H('398.d.8.H',3,"A universal testing machine is used to pull a sample until it breaks and record its:","load and elongation",["color","price","name"],"UTMs record load-deflection data.")
H('398.d.8.H',4,"Setting up a material test requires controlling conditions such as the loading rate and the:","temperature",["day of the week","tester's age","paper size"],"Conditions affect results.")
H('398.d.9.A',3,"Using g = 9.8 meters per second squared, the weight of a 5-kilogram object is:","49 newtons",["5 newtons","14.8 newtons","0.51 newtons"],"W = m x g = 5 x 9.8.")
H('398.d.9.A',4,"A part weighs 196 newtons on Earth. Its mass is:","20 kilograms",["196 kilograms","1,920.8 kilograms","2 kilograms"],"196 / 9.8 = 20.")
H('398.d.9.B',3,"Torque is calculated by multiplying a force by the perpendicular:","distance to the axis",["time","voltage","color"],"T = F x d.")
H('398.d.9.B',4,"A torque of 15 pound-feet results from a 5-pound force applied at a lever arm of:","3 feet",["75 feet","10 feet","0.33 feet"],"15 / 5 = 3.")
H('398.d.9.C',3,"A torque of 60 newton-meters is applied at a radius of 0.3 meters. The tangential force is:","200 newtons",["18 newtons","60.3 newtons","20 newtons"],"60 / 0.3.")
H('398.d.9.C',4,"For the same torque, doubling the radius makes the tangential force:","half as large",["twice as large","the same","zero"],"F = T / r.")
H('398.d.9.D',3,"A lever's ideal mechanical advantage equals its effort arm length divided by its:","load arm length",["weight","color","height"],"IMA = effort arm / load arm.")
H('398.d.9.D',4,"A second-class lever has a 100-centimeter effort arm and a 25-centimeter load arm. Its mechanical advantage is:","4",["0.25","75","125"],"100 / 25.")
H('398.d.9.E',3,"A wheelbarrow is a second-class lever, which always has a mechanical advantage that is:","greater than 1",["less than 1","exactly zero","negative"],"The load sits between the fulcrum and effort.")
H('398.d.9.E',4,"A third-class lever, such as a fishing rod, gains in speed and distance but has a mechanical advantage that is:","less than 1",["greater than 1","infinite","exactly 1 always"],"The effort is between fulcrum and load.")
H('398.d.9.F',3,"A 20-newton friction force acts when a 100-newton normal force presses on two surfaces. The coefficient of friction is:","0.2",["5","120","80"],"20 / 100.")
H('398.d.9.F',4,"The coefficient of friction has units of:","none (it is a ratio)",["newtons","meters","seconds"],"It is force divided by force.")
H('398.d.9.G',3,"A ramp 10 meters long raises a load 2 meters. Its ideal mechanical advantage is:","5",["20","0.2","8"],"10 / 2.")
H('398.d.9.G',4,"A pulley system supported by 4 rope segments has an ideal mechanical advantage of:","4",["1","2","16"],"MA equals the number of supporting segments.")
H('398.d.9.H',3,"A 15-tooth driver gear turns a 45-tooth driven gear. The gear drive's mechanical advantage is:","3",["30","0.33","60"],"45 / 15.")
H('398.d.9.H',4,"A gear drive that multiplies torque by 3 reduces output speed to:","one-third of the input speed",["three times the input speed","the same speed","zero"],"Speed and torque trade off.")
H('398.d.9.I',3,"A drive that carries a steady, unchanging load has a load type called:","constant",["shock","random","absent"],"Steady loads do not fluctuate.")
H('398.d.9.I',4,"A drive that drives a rock crusher, with sudden jolts, must be rated for:","shock loading",["no load","zero torque","light duty only"],"Shock loads require higher service factors.")
H('398.d.9.J',3,"A shaft delivers 10 newton-meters at 100 radians per second. The power is:","1,000 watts",["10 watts","110 watts","0.1 watts"],"P = T x omega.")
H('398.d.9.J',4,"If the torque on a shaft is doubled at the same angular speed, the power:","doubles",["halves","stays the same","drops to zero"],"P = T x omega.")
H('398.d.9.K',3,"A mechanism takes in 1,000 watts and delivers 800 watts. Its mechanical efficiency is:","80 percent",["125 percent","20 percent","1.25 percent"],"800 / 1,000.")
H('398.d.9.K',4,"The efficiency of a real mechanism is always:","less than 100 percent",["more than 100 percent","exactly 100 percent","below zero"],"Friction wastes some power.")
H('398.d.9.L',3,"The pitch of a thread is the distance between adjacent:","threads",["colors","washers","labels"],"Pitch measures thread spacing.")
H('398.d.9.L',4,"In a chain drive, the pitch is the distance between the centers of adjacent:","chain pins",["wheels","bolts","bearings only"],"Chain pitch is pin-to-pin.")
H('398.d.9.M',3,"A 4-inch driver pulley turns at 1,200 revolutions per minute and drives an 8-inch pulley by belt. The driven pulley turns at:","600 revolutions per minute",["2,400 revolutions per minute","1,200 revolutions per minute","300 revolutions per minute"],"Speed is inversely proportional to diameter.")
H('398.d.9.M',4,"In the same belt drive, the output torque compared with the input torque (ignoring losses) is:","twice as large",["half as large","the same","zero"],"Slower output means higher torque.")
H('398.d.9.N',3,"A 12-tooth driver sprocket drives a 36-tooth driven sprocket. The sprocket ratio is:","3 to 1",["1 to 3","12 to 1","36 to 12 speed-up"],"36 / 12.")
H('398.d.9.N',4,"A bicycle uses a larger rear sprocket for climbing hills because it provides more:","torque at the wheel",["speed","noise","friction at the chain"],"A bigger driven sprocket multiplies torque.")
H('398.d.10.A',3,"A micrometer's sleeve reads 0.275 inch and the thimble adds 0.013 inch. The measurement is:","0.288 inch",["0.262 inch","0.275 inch","0.013 inch"],"0.275 + 0.013.")
H('398.d.10.A',4,"A dial caliper shows 1.2 on the main scale and 0.035 on the dial. The measurement is:","1.235 inches",["1.2 inches","1.165 inches","0.035 inches"],"1.2 + 0.035.")
H('398.d.10.B',3,"The three common measures of central tendency are the mean, the median, and the:","mode",["range","variance","outlier"],"Mean, median, and mode.")
H('398.d.10.B',4,"In the data 5, 7, 7, 9, 12, the mode is:","7",["5","9","12"],"7 occurs most often.")
H('398.d.10.C',3,"To build a histogram by hand, group the data into:","intervals and count the frequency in each",["colors","names","weights only"],"Histograms count values per class.")
H('398.d.10.C',4,"A histogram of part diameters that is centered on the target with a narrow spread suggests a process that is:","consistent",["out of control","random","dangerous"],"Narrow and centered means consistent.")
H('398.d.10.D',3,"On a mean-and-range chart, a point outside the control limits signals that the process may be:","out of control",["perfect","finished","free"],"Points beyond limits show special causes.")
H('398.d.10.D',4,"The range chart in a mean-and-range pair monitors the process's:","variation",["color","cost","price"],"R charts track spread.")
H('398.d.10.E',3,"A dimension of 1.500 inches with a tolerance of plus or minus 0.010 inch has a minimum limit of:","1.490 inches",["1.510 inches","1.500 inches","1.400 inches"],"1.500 - 0.010.")
H('398.d.10.E',4,"A part measures 1.512 inches against limits of 1.490 to 1.510. The part is:","out of tolerance",["in tolerance","perfect","undersized"],"1.512 exceeds the upper limit.")
H('398.d.10.F',3,"Position tolerance gives a zone, often a circle, within which a hole's center must lie around its:","true position",["color","price","label"],"The zone surrounds the exact location.")
H('398.d.10.F',4,"A hole's center is 0.003 inch off its true position in both the X and Y directions. Its distance from true position is about:","0.0042 inch",["0.006 inch","0.003 inch","0.0003 inch"],"sqrt(0.003^2 + 0.003^2) = 0.00424.")

